import { LitElement, css, html, nothing } from "lit";
import { customElement, property, state } from "lit/decorators.js";
import type { Ctx } from "../ctx";
import type { ProConfig } from "../types";
import { clone, normalize } from "../config";
import { areas, domainOf, nameOf, isOn, powerKw } from "../ha";
import { shared } from "../styles";
import { fieldStyles } from "./fields";
import { getPreferences, savePreferences } from "../experience";

type Section = "overview" | "search" | "alerts" | "maintenance" | "preferences" | "backup" | "license" | "access" | "activity" | "schedules" | "energy" | "help";
type Alert = { id: string; title: string; detail: string; severity: "high" | "normal"; entity?: string };
type History = { id: string; created_at: number | string; config: ProConfig };
type Activity = { at: number | string; user: string; domain: string; service: string; entities: string[]; success: boolean; from_state?: string; to_state?: string };
type Schedule = { id: string; entity_id: string; at: string };

export function openHomeCenter(c: Ctx, section = "overview") {
  c.showSheet({ title: c.lang === "ar" ? "مركز البيت" : "Home center", wide: true, render: cc => html`<sn-home-center .ctx=${cc} .initial=${section}></sn-home-center>` });
}

@customElement("sn-home-center")
export class HomeCenter extends LitElement {
  @property({ attribute: false }) ctx!: Ctx;
  @property() initial = "overview";
  @state() private section: Section = "overview";
  @state() private query = "";
  @state() private severity = "all";
  @state() private busy = false;
  @state() private notice = "";
  @state() private failed = false;
  @state() private versions: History[] = [];
  @state() private activity: Activity[] = [];
  @state() private schedules: Schedule[] = [];
  @state() private license?: { valid: boolean; reason: string; expires_at?: number | null; offline_until?: number | null; customer_name?: string };
  @state() private imported?: ProConfig;
  @state() private taskTitle = "";
  @state() private taskDue = new Date(Date.now() + 86400000).toISOString().slice(0, 10);
  @state() private taskEntity = "";
  @state() private taskInterval = 0;
  @state() private scheduleEntity = "";
  @state() private scheduleAt = "";
  @state() private accessUser = "";
  @state() private accessAreas: string[] = [];
  @state() private accessEntities: string[] = [];
  @state() private guestDays = 0;
  @state() private users: { id: string; name: string; is_active?: boolean }[] = [];
  @state() private copyFrom = "";
  @state() private copyTo = "";
  @state() private tourStep = 0;
  @state() private connectionResult?: { checkedAt: string; ok: boolean; latency?: number; validLicense?: boolean };
  private loadCycle = 0;
  @state() private draggedPage = "";

  private tr(ar: string, en: string) { return this.ctx.lang === "ar" ? ar : en; }
  private get exp() { return this.ctx.config.experience ?? {}; }
  private get prefs() { return getPreferences(this.ctx.hass); }
  private get entities() { return Object.values(this.ctx.hass.states); }
  private get sceneIds() { return Object.keys(this.ctx.hass.states).filter(id => ["scene", "script"].includes(domainOf(id))).sort((a, b) => nameOf(this.ctx.hass, a).localeCompare(nameOf(this.ctx.hass, b))); }
  private get admin() { return this.ctx.isAdmin; }
  private suggestedScene(kind: "leave" | "sleep") {
    const match = kind === "leave" ? /leave|away|goodbye|مغادر|خروج|خارج/iu : /sleep|good.?night|bed.?time|night|نوم|تصبح|ليلة|ليل/iu;
    return this.sceneIds.find(id => match.test(nameOf(this.ctx.hass, id) + " " + id));
  }
  private scenePreview(id: string | undefined) {
    if (!id) return this.tr("اختر المشهد أولًا.", "Choose a scene first.");
    const entity = this.ctx.hass.states[id];
    const ids: string[] = domainOf(id) === "scene" && Array.isArray(entity?.attributes.entity_id) ? entity.attributes.entity_id.filter((value: unknown): value is string => typeof value === "string") : [];
    if (!ids.length) return this.tr("تفاصيل الأجهزة المتأثرة غير متاحة هنا. راجع إعداد المشهد أو السكربت في Home Assistant قبل تشغيله.", "Affected-entity details are unavailable here. Review the scene or script in Home Assistant before running it.");
    const visible = ids.filter(value => !!this.ctx.hass.states[value]);
    const lines = visible.slice(0, 20).map(value => nameOf(this.ctx.hass, value));
    const extra = ids.length - lines.length;
    return this.tr("الأجهزة المرتبطة بهذا المشهد: ", "Entities linked to this scene: ") + lines.join("، ") + (extra ? this.tr("؛ وأجهزة أخرى لا تظهر تفاصيلها هنا: ", "; additional entities not detailed here: ") + extra : "");
  }
  private fieldHelp(ar: string, en: string) { return html`<small class="field-help">${this.tr(ar, en)}</small>`; }
  private movePage(id: string, target: string, order: string[]) {
    if (id === target || !order.includes(id) || !order.includes(target)) return;
    const next = [...order]; const from = next.indexOf(id), to = next.indexOf(target);
    next.splice(from, 1); next.splice(to, 0, id); this.updatePrefs({ page_order: next }); this.draggedPage = "";
  }

  connectedCallback() { super.connectedCallback(); this.section = this.validSection(this.initial); void this.loadSection(); }
  disconnectedCallback() { this.loadCycle++; super.disconnectedCallback(); }
  private validSection(value: string): Section {
    return ["overview", "search", "alerts", "maintenance", "preferences", "backup", "license", "access", "activity", "schedules", "energy", "help"].includes(value) ? value as Section : "overview";
  }
  private async changeSection(value: Section) { this.section = value; this.notice = ""; this.failed = false; await this.loadSection(); }
  private async loadSection() {
    const cycle = ++this.loadCycle;
    this.busy = true;
    try {
      const c = this.ctx;
      if (this.section === "license") {
        const result = await c.hass.callWS<typeof this.license>({ type: "smartnest_pro/license/status" });
        if (cycle === this.loadCycle) this.license = result;
      } else if (this.section === "backup" && this.admin) {
        const result = await c.hass.callWS<{ versions: History[] }>({ type: "smartnest_pro/config/history" });
        if (cycle === this.loadCycle) this.versions = result.versions ?? [];
      } else if (this.section === "activity" && this.admin) {
        const result = await c.hass.callWS<{ events: Activity[] }>({ type: "smartnest_pro/activity/list" });
        if (cycle === this.loadCycle) this.activity = result.events ?? [];
      } else if (this.section === "schedules" && this.admin) {
        const result = await c.hass.callWS<{ schedules: Schedule[] }>({ type: "smartnest_pro/schedule/list" });
        if (cycle === this.loadCycle) this.schedules = result.schedules ?? [];
      } else if (this.section === "access" && this.admin) {
        try {
          const result = await c.hass.callWS<{ id: string; name: string; is_active?: boolean }[]>({ type: "config/auth/list" });
          if (cycle === this.loadCycle) this.users = Array.isArray(result) ? result : [];
        } catch { if (cycle === this.loadCycle) this.users = []; }
      }
    } catch (error) { if (cycle === this.loadCycle) this.error(error); }
    finally { if (cycle === this.loadCycle) this.busy = false; }
  }
  private error(error: unknown) { this.failed = true; this.notice = error instanceof Error ? error.message : this.tr("تعذّر تنفيذ الطلب. تحقق من الاتصال والصلاحيات.", "Request failed. Check your connection and permissions."); }
  private async run(work: () => Promise<void>) { if (this.busy) return; this.busy = true; this.notice = ""; this.failed = false; try { await work(); } catch (error) { this.error(error); } finally { this.busy = false; } }
  private updateExperience(fn: (e: NonNullable<ProConfig["experience"]>) => void) {
    if (!this.admin) return;
    this.ctx.saveLayout(config => { config.experience ??= {}; fn(config.experience); });
  }
  private updatePrefs(patch: Parameters<typeof savePreferences>[1]) { savePreferences(this.ctx.hass, patch); this.requestUpdate(); this.ctx.toast(this.tr("تم تحديث تفضيلاتك لهذه الشاشة.", "Your preferences for this screen were updated.")); }
  private format(value: number | string | undefined | null) {
    if (value == null) return this.tr("غير محدد", "Not set");
    const date = new Date(typeof value === "number" ? value * 1000 : value);
    return Number.isNaN(date.getTime()) ? this.tr("غير معروف", "Unknown") : date.toLocaleString(this.ctx.lang === "ar" ? "ar-u-ca-gregory" : "en", { dateStyle: "medium", timeStyle: "short" });
  }
  private entitySelect(value: string, change: (value: string) => void, ids = Object.keys(this.ctx.hass.states)) {
    return html`<select .value=${value} @change=${(event: Event) => change((event.target as HTMLSelectElement).value)}><option value="">${this.tr("اختر جهازًا", "Choose an entity")}</option>${ids.map(id => html`<option value=${id} ?selected=${value === id}>${nameOf(this.ctx.hass, id)}</option>`)}</select>`;
  }
  private favorite(id: string) {
    const current = this.prefs.favorites ?? [];
    this.updatePrefs({ favorites: current.includes(id) ? current.filter((value: string) => value !== id) : [...current, id] });
  }
  private download(name: string, content: unknown) {
    const url = URL.createObjectURL(new Blob([JSON.stringify(content, null, 2)], { type: "application/json" }));
    const anchor = document.createElement("a"); anchor.href = url; anchor.download = name; anchor.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  private missingLinks(): string[] {
    const missing = new Set<string>();
    const walk = (value: unknown, key = "") => {
      if (typeof value === "string" && /^[a-z_]+\.[a-z0-9_]+$/.test(value) && !["title", "name", "image", "url", "kiosk_pin"].includes(key) && !this.ctx.hass.states[value]) missing.add(value);
      else if (Array.isArray(value)) value.forEach(item => walk(item, key));
      else if (value && typeof value === "object") Object.entries(value).forEach(([name, item]) => walk(item, name));
    };
    // Only entity-bearing configuration is checked; arbitrary notes and display labels are excluded.
    [this.ctx.config.home, this.ctx.config.rooms, this.ctx.config.door, this.ctx.config.plan].forEach(value => walk(value));
    return [...missing];
  }
  private alerts(): Alert[] {
    const found: Alert[] = [];
    for (const entity of this.entities) {
      const name = nameOf(this.ctx.hass, entity.entity_id);
      if (["unavailable", "unknown"].includes(entity.state)) found.push({ id: "offline:" + entity.entity_id, title: name, detail: this.tr("غير متصل أو لا تتوفر بيانات", "Unavailable or unknown"), severity: "normal", entity: entity.entity_id });
      if (entity.attributes.device_class === "battery" && Number.isFinite(Number(entity.state)) && Number(entity.state) <= 20) found.push({ id: "battery:" + entity.entity_id, title: name, detail: this.tr("البطارية منخفضة: ", "Low battery: ") + entity.state + "%", severity: "normal", entity: entity.entity_id });
      if (["door", "window", "garage_door"].includes(entity.attributes.device_class) && entity.state === "on") found.push({ id: "door:" + entity.entity_id, title: name, detail: this.tr("باب أو نافذة مفتوحة", "Door or window open"), severity: "high", entity: entity.entity_id });
    }
    for (const id of this.missingLinks()) found.push({ id: "missing:" + id, title: id, detail: this.tr("رابط جهاز غير موجود؛ افتح إعداداته لاستبداله.", "Missing entity link. Replace it in settings."), severity: "normal" });
    const now = new Date().toISOString().slice(0, 10);
    for (const task of this.exp.maintenance ?? []) if (task.due <= now) found.push({ id: "maintenance:" + task.id, title: task.title, detail: this.tr("موعد الصيانة: ", "Maintenance due: ") + task.due, severity: "normal", entity: task.entity });
    const threshold = this.exp.power_alert_kw;
    const powerId = this.exp.power_entity;
    const kw = powerId ? powerKw(this.ctx.hass.states[powerId]) : undefined;
    if (powerId && typeof threshold === "number" && threshold > 0 && kw != null && kw > threshold) found.push({ id: "power", title: this.tr("استهلاك أعلى من الحد", "Power above your threshold"), detail: `${nameOf(this.ctx.hass, powerId)}: ${kw.toFixed(2)} kW`, severity: "high", entity: powerId });
    return found.sort((a, b) => (a.severity === "high" ? 0 : 1) - (b.severity === "high" ? 0 : 1));
  }
  private dndActive() {
    const dnd = this.exp.dnd;
    if (!dnd?.enabled) return false;
    const now = new Date(); const time = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
    return dnd.start <= dnd.end ? time >= dnd.start && time < dnd.end : time >= dnd.start || time < dnd.end;
  }
  private renderOverview() {
    const counts = { lights: this.entities.filter(e => domainOf(e.entity_id) === "light" && e.state === "on").length, doors: this.entities.filter(e => ["door", "window"].includes(e.attributes.device_class) && e.state === "on").length, climate: this.entities.filter(e => domainOf(e.entity_id) === "climate" && isOn(e)).length, offline: this.entities.filter(e => ["unavailable", "unknown"].includes(e.state)).length };
    return html`<h3>${this.tr("بيتك بنظرة واحدة", "Your home at a glance")}</h3><div class="metrics">${Object.entries(counts).map(([key, count]) => html`<div><strong>${count}</strong><span>${({ lights: this.tr("أضواء تعمل", "Lights on"), doors: this.tr("أبواب مفتوحة", "Open doors"), climate: this.tr("تكييف يعمل", "Climate active"), offline: this.tr("أجهزة غير متصلة", "Unavailable") })[key]}</span></div>`)}</div><div class="grid">${(["leave", "sleep"] as const).map(kind => html`<article><h4>${kind === "leave" ? this.tr("مغادرة البيت", "Leave home") : this.tr("وقت النوم", "Bedtime")}</h4><p>${this.exp.quick_scenes?.[kind] ? nameOf(this.ctx.hass, this.exp.quick_scenes[kind]!) : this.tr("اختر المشهد الذي تريد تنفيذه.", "Choose a scene to run.")}</p>${this.exp.quick_scenes?.[kind] ? html`<details><summary>${this.tr("معاينة الأجهزة المتأثرة", "Preview affected entities")}</summary><p>${this.scenePreview(this.exp.quick_scenes[kind])}</p></details>` : nothing}${this.admin ? html`${this.entitySelect(this.exp.quick_scenes?.[kind] ?? "", value => this.updateExperience(e => { e.quick_scenes ??= {}; e.quick_scenes[kind] = value || undefined; }), this.sceneIds)}${!this.exp.quick_scenes?.[kind] && this.suggestedScene(kind) ? html`<p class="hint">${this.tr("اقتراح من مشاهد بيتك الحالية: ", "Suggested from your existing home scenes: ")}${nameOf(this.ctx.hass, this.suggestedScene(kind)!)}</p><button class="subtle" @click=${() => this.updateExperience(e => { e.quick_scenes ??= {}; e.quick_scenes[kind] = this.suggestedScene(kind); })}>${this.tr("استخدم هذا الاقتراح", "Use this suggestion")}</button>` : nothing}` : nothing}<button ?disabled=${!this.exp.quick_scenes?.[kind] || this.busy} @click=${() => this.run(async () => { const id = this.exp.quick_scenes?.[kind]; if (!id || !window.confirm(this.tr("سيتم تشغيل المشهد: ", "Run scene: ") + nameOf(this.ctx.hass, id) + "\n\n" + this.scenePreview(id) + "\n\n" + this.tr("متابعة التنفيذ؟", "Continue?"))) return; const result = await this.ctx.hass.callService(domainOf(id), "turn_on", { entity_id: id }); this.notice = result?.success === true ? this.tr("تم تنفيذ المشهد.", "Scene completed.") : this.tr("لم يتم تشغيل المشهد؛ أُلغي الطلب أو لم يرد تأكيد التنفيذ.", "The scene was not run; the request was canceled or no execution confirmation was returned."); })}>${this.tr("معاينة وتشغيل", "Review and run")}</button></article>`)}</div><h4>${this.tr("مفضلتك", "Your favorites")}</h4><div class="results">${(this.prefs.favorites ?? []).filter((id: string) => this.ctx.hass.states[id]).map((id: string) => html`<button @click=${() => this.ctx.openEntity(id)}>${nameOf(this.ctx.hass, id)}</button>`)}</div><button class="subtle" @click=${() => this.changeSection("search")}>${this.tr("تعديل المفضلة والبحث عن الأجهزة", "Find entities and edit favorites")}</button>`;
  }
  private renderSearch() {
    const query = this.query.trim().toLocaleLowerCase();
    const roomMatches = areas(this.ctx.hass).filter(area => !query || area.name.toLocaleLowerCase().includes(query));
    const matches = this.entities.filter(entity => !query || (nameOf(this.ctx.hass, entity.entity_id) + " " + entity.entity_id).toLocaleLowerCase().includes(query)).slice(0, 80);
    return html`<label class="field"><span>${this.tr("بحث شامل بالغرف والأجهزة والمشاهد", "Search rooms, entities and scenes")}</span><input type="search" .value=${this.query} @input=${(event: Event) => this.query = (event.target as HTMLInputElement).value} placeholder=${this.tr("اكتب الاسم…", "Type a name…")}></label><h4>${this.tr("الغرف", "Rooms")}</h4><div class="results">${roomMatches.map(area => html`<button @click=${() => { this.ctx.selectRoom(area.area_id); this.ctx.closeSheet(); }}>${this.ctx.config.rooms[area.area_id]?.name || area.name}</button>`)}</div><h4>${this.tr("الأجهزة والمشاهد", "Entities and scenes")}</h4><p class="hint">${this.tr("يعرض حتى ٨٠ نتيجة. وقت التحديث لا يعني أن الجهاز الثابت معطّل.", "Shows up to 80 results. An old update time does not mean an unchanged device is faulty.")}</p><div class="list">${matches.map(entity => html`<article class="row"><button class="entity" @click=${() => this.ctx.openEntity(entity.entity_id)}><strong>${nameOf(this.ctx.hass, entity.entity_id)}</strong><small>${entity.state} · ${this.tr("آخر تحديث: ", "Updated: ")}${this.format(entity.last_updated)}</small></button><button class="star" aria-label=${this.tr("تبديل المفضلة", "Toggle favorite")} aria-pressed=${(this.prefs.favorites ?? []).includes(entity.entity_id)} @click=${() => this.favorite(entity.entity_id)}>${(this.prefs.favorites ?? []).includes(entity.entity_id) ? "★" : "☆"}</button></article>`)}</div>`;
  }
  private renderAlerts() {
    const dnd = this.dndActive(); const all = this.alerts(); const alerts = all.filter(alert => (this.severity === "all" || this.severity === alert.severity) && (!dnd || alert.severity === "high"));
    return html`<h3>${this.tr("التنبيهات", "Notifications")}</h3>${dnd ? html`<p class="hint">${this.tr("عدم الإزعاج نشط. التنبيهات العادية مخفية حاليًا؛ التنبيهات المهمة تبقى ظاهرة.", "Do not disturb is active. Ordinary alerts are hidden; important alerts remain visible.")}</p>` : nothing}<label class="field"><span>${this.tr("الأهمية", "Priority")}</span>${this.fieldHelp("الأبواب المفتوحة وتجاوز قدرة البيت تُعرض كتنبيهات مهمة.", "Open doors and home-power threshold breaches are marked important.")}<select .value=${this.severity} @change=${(event: Event) => this.severity = (event.target as HTMLSelectElement).value}><option value="all">${this.tr("الكل", "All")}</option><option value="high">${this.tr("مهمة", "Important")}</option><option value="normal">${this.tr("عادية", "Ordinary")}</option></select></label>${alerts.length ? alerts.map(alert => html`<article class="row"><div><strong>${alert.severity === "high" ? "● " : ""}${alert.title}</strong><p>${alert.detail}</p>${alert.entity ? html`<small>${this.tr("آخر تحديث: ", "Updated: ")}${this.format(this.ctx.hass.states[alert.entity]?.last_updated)}</small>` : nothing}</div>${alert.entity && this.ctx.hass.states[alert.entity] ? html`<button @click=${() => this.ctx.openEntity(alert.entity!)}>${this.tr("فتح", "Open")}</button>` : nothing}</article>`) : html`<p>${this.tr("لا توجد تنبيهات مطابقة الآن.", "No matching notifications right now.")}</p>`}${this.admin ? html`<h4>${this.tr("عدم الإزعاج", "Do not disturb")}</h4><label class="check"><input type="checkbox" .checked=${!!this.exp.dnd?.enabled} @change=${(event: Event) => this.updateExperience(e => e.dnd = { start: e.dnd?.start ?? "22:00", end: e.dnd?.end ?? "07:00", enabled: (event.target as HTMLInputElement).checked })}>${this.tr("إخفاء التنبيهات العادية في الوقت المحدد", "Hide ordinary alerts during these hours")}</label><div class="grid">${(["start", "end"] as const).map(key => html`<label class="field"><span>${key === "start" ? this.tr("من", "From") : this.tr("حتى", "Until")}</span><input type="time" .value=${this.exp.dnd?.[key] ?? (key === "start" ? "22:00" : "07:00")} @change=${(event: Event) => this.updateExperience(e => { e.dnd ??= { enabled: false, start: "22:00", end: "07:00" }; e.dnd[key] = (event.target as HTMLInputElement).value; })}></label>`)}</div>` : nothing}`;
  }
  private renderMaintenance() {
    const tasks = this.exp.maintenance ?? [];
    return html`<h3>${this.tr("صيانة البيت", "Home maintenance")}</h3>${tasks.map(task => html`<article class="row"><div><strong>${task.title}</strong><p>${task.due}${task.entity ? " · " + nameOf(this.ctx.hass, task.entity) : ""}</p></div>${this.admin ? html`<button @click=${() => this.updateExperience(e => { e.maintenance = (e.maintenance ?? []).flatMap(item => { if (item.id !== task.id) return [item]; if (!item.interval_days) return []; const due = new Date(); due.setDate(due.getDate() + item.interval_days); return [{ ...item, due: due.toISOString().slice(0, 10) }]; }); })}>${this.tr("تمت الصيانة", "Mark complete")}</button>` : nothing}</article>`)}${!tasks.length ? html`<p>${this.tr("لا توجد مهام صيانة مسجلة.", "No maintenance tasks yet.")}</p>` : nothing}${this.admin ? html`<form @submit=${(event: Event) => { event.preventDefault(); if (!this.taskTitle.trim() || !this.taskDue) return; this.updateExperience(e => { e.maintenance ??= []; e.maintenance.push({ id: crypto.randomUUID(), title: this.taskTitle.trim().slice(0, 120), entity: this.taskEntity || undefined, due: this.taskDue, interval_days: this.taskInterval || undefined }); }); this.taskTitle = ""; }}><h4>${this.tr("تذكير جديد", "New reminder")}</h4><label class="field"><span>${this.tr("اسم المهمة", "Task title")}</span>${this.fieldHelp("مثال: تنظيف فلتر المكيف. هذا تذكير فقط ولا يشغّل جهازًا.", "For example, clean the AC filter. This is a reminder and does not operate an entity.")}<input required type="text" maxlength="120" .value=${this.taskTitle} @input=${(event: Event) => this.taskTitle = (event.target as HTMLInputElement).value}></label><div class="grid"><label class="field"><span>${this.tr("تاريخ الاستحقاق", "Due date")}</span>${this.fieldHelp("يظهر التذكير في التنبيهات عند حلول هذا التاريخ.", "The reminder appears in notifications when this date arrives.")}<input required type="date" .value=${this.taskDue} @change=${(event: Event) => this.taskDue = (event.target as HTMLInputElement).value}></label><label class="field"><span>${this.tr("التكرار بالأيام؛ صفر لمرة واحدة", "Repeat days; zero for once")}</span>${this.fieldHelp("بعد إتمام الصيانة يُحدد الموعد التالي بعد هذا العدد من الأيام.", "After completion, the next due date is this many days later.")}<input type="number" min="0" max="3650" .value=${String(this.taskInterval)} @change=${(event: Event) => this.taskInterval = Math.max(0, Number((event.target as HTMLInputElement).value))}></label></div><label class="field"><span>${this.tr("جهاز مرتبط (اختياري)", "Related entity (optional)")}</span>${this.entitySelect(this.taskEntity, value => this.taskEntity = value)}</label><button>${this.tr("إضافة التذكير", "Add reminder")}</button></form>` : nothing}`;
  }
  private renderPreferences() {
    const prefs = this.prefs; const order = prefs.page_order?.length ? prefs.page_order : ["home", "rooms", "climate", "lights", "robot", "family", "energy", "security", "media"];
    const labels: Record<string, string> = { home: this.tr("البيت", "Home"), rooms: this.tr("الغرف", "Rooms"), climate: this.tr("التكييف", "Climate"), lights: this.tr("الإضاءة", "Lights"), robot: this.tr("المكنسة", "Robot"), family: this.tr("العائلة", "Family"), energy: this.tr("الطاقة", "Energy"), security: this.tr("الأمان", "Security"), media: this.tr("الوسائط", "Media") };
    return html`<h3>${this.tr("تفضيلاتك", "Your preferences")}</h3><label class="field"><span>${this.tr("صفحة البداية لحسابك", "Your account start page")}</span>${this.fieldHelp("تتزامن مع شاشاتك الأخرى عند توفر الاتصال.", "Syncs to your other screens when connected.")}<select .value=${prefs.start_page ?? "home"} @change=${(event: Event) => this.updatePrefs({ start_page: (event.target as HTMLSelectElement).value })}>${Object.entries(labels).map(([id, label]) => html`<option value=${id} ?selected=${(prefs.start_page ?? "home") === id}>${label}</option>`)}</select></label><label class="field"><span>${this.tr("صفحة بداية خاصة بهذه الشاشة", "Start page for this screen only")}</span>${this.fieldHelp("مفيد لعرض المخطط على التابلت والمفضلة على الهاتف. هذا الاختيار يبقى على هذه الشاشة.", "Useful for a floor plan on the tablet and another page on your phone. This override stays on this screen.")}<select .value=${prefs.screen_start_page ?? ""} @change=${(event: Event) => this.updatePrefs({ screen_start_page: (event.target as HTMLSelectElement).value || undefined })}><option value="" ?selected=${!prefs.screen_start_page}>${this.tr("استخدم تفضيل الحساب", "Use account preference")}</option>${Object.entries(labels).map(([id, label]) => html`<option value=${id} ?selected=${prefs.screen_start_page === id}>${label}</option>`)}</select></label><label class="check"><input type="checkbox" .checked=${!!prefs.simple_mode} @change=${(event: Event) => this.updatePrefs({ simple_mode: (event.target as HTMLInputElement).checked })}>${this.tr("واجهة مبسّطة", "Simple interface")}</label>${this.fieldHelp("تقل التفاصيل الظاهرة مع بقاء الوظائف الأساسية متاحة.", "Reduces visible detail while keeping essential controls available.")}<label class="check"><input type="checkbox" .checked=${!!prefs.high_contrast} @change=${(event: Event) => this.updatePrefs({ high_contrast: (event.target as HTMLInputElement).checked })}>${this.tr("تباين مرتفع", "High contrast")}</label><label class="field"><span>${this.tr("حجم النص", "Text size")}</span><select .value=${String(prefs.font_scale ?? 1)} @change=${(event: Event) => this.updatePrefs({ font_scale: Number((event.target as HTMLSelectElement).value) })}><option value="1">100%</option><option value="1.15">115%</option><option value="1.3">130%</option><option value="1.5">150%</option></select></label><h4>${this.tr("ترتيب الصفحات", "Page order")}</h4><p class="hint">${this.tr("اسحب الصفحة لترتيبها، أو استخدم السهمين بلوحة المفاتيح أو على الهاتف.", "Drag pages to reorder, or use the arrow buttons with a keyboard or on a phone.")}</p><div role="list">${order.map((id: string, index: number) => html`<div class="row page-drag" role="listitem" draggable="true" @dragstart=${(event: DragEvent) => { this.draggedPage = id; event.dataTransfer?.setData("text/plain", id); if (event.dataTransfer) event.dataTransfer.effectAllowed = "move"; }} @dragend=${() => this.draggedPage = ""} @dragover=${(event: DragEvent) => { if (this.draggedPage) event.preventDefault(); }} @drop=${(event: DragEvent) => { event.preventDefault(); const source = this.draggedPage || event.dataTransfer?.getData("text/plain") || ""; this.movePage(source, id, order); }}><span>⋮⋮ ${labels[id] ?? id}</span><div><button class="subtle" ?disabled=${index === 0} aria-label=${this.tr("تقديم الصفحة", "Move page earlier")} @click=${() => { const next = [...order]; [next[index - 1], next[index]] = [next[index], next[index - 1]]; this.updatePrefs({ page_order: next }); }}>↑</button><button class="subtle" ?disabled=${index === order.length - 1} aria-label=${this.tr("تأخير الصفحة", "Move page later")} @click=${() => { const next = [...order]; [next[index + 1], next[index]] = [next[index], next[index + 1]]; this.updatePrefs({ page_order: next }); }}>↓</button></div></div>`)}</div>${this.admin ? html`<h4>${this.tr("جودة العرض والمخطط", "Display and floor-plan quality")}</h4><label class="field"><span>${this.tr("أداء الرسوم", "Graphics performance")}</span>${this.fieldHelp("التلقائي يختار جودة أخف للأجهزة محدودة الأداء. اختر خفيفًا للتابلت القديم.", "Auto chooses lighter rendering for limited devices. Choose light for older tablets.")}<select .value=${this.ctx.config.settings.performance ?? "auto"} @change=${(event: Event) => this.ctx.saveLayout(config => config.settings.performance = (event.target as HTMLSelectElement).value as "auto" | "light" | "high")}><option value="auto">${this.tr("تلقائي", "Auto")}</option><option value="light">${this.tr("خفيف", "Light")}</option><option value="high">${this.tr("جودة عالية", "High quality")}</option></select></label><label class="field"><span>${this.tr("عرض المخطط", "Floor-plan view")}</span>${this.fieldHelp("العرض الثنائي يظهر المخطط من الأعلى لتسهيل القراءة والتحكم.", "The 2D view shows your plan from above for easier reading and controls.")}<select .value=${this.ctx.config.settings.plan_view ?? "3d"} @change=${(event: Event) => this.ctx.saveLayout(config => config.settings.plan_view = (event.target as HTMLSelectElement).value as "2d" | "3d")}><option value="3d">${this.tr("ثلاثي الأبعاد", "3D")}</option><option value="2d">${this.tr("ثنائي الأبعاد", "2D")}</option></select></label>` : nothing}`;
  }
  private async importFile(event: Event) {
    const input = event.target as HTMLInputElement; const file = input.files?.[0]; input.value = ""; if (!file) return;
    await this.run(async () => {
      if (file.size > 1024 * 1024) throw new Error(this.tr("الملف أكبر من ١ ميغابايت.", "File is larger than 1 MB."));
      const raw = JSON.parse(await file.text());
      if (!raw || raw.version !== 1 || !raw.settings || typeof raw.settings !== "object" || Array.isArray(raw.settings) || !raw.hero || typeof raw.hero !== "object" || Array.isArray(raw.hero) || !raw.rooms || typeof raw.rooms !== "object" || Array.isArray(raw.rooms) || !Array.isArray(raw.plan?.floors)) throw new Error(this.tr("هذا الملف ليس نسخة إعدادات SmartNest صالحة.", "This is not a valid SmartNest configuration backup."));
      this.imported = normalize(raw);
    });
  }
  private restore(config: ProConfig) {
    if (!this.admin || !window.confirm(this.tr("تطبيق هذه النسخة سيستبدل التصميم الحالي. متابعة؟", "This will replace the current layout. Continue?"))) return;
    const replacement = clone(normalize(config));
    this.ctx.saveLayout(draft => {
      // A restore replaces the full layout, including optional features absent in
      // the backup. Current access rules and the editing PIN remain local policy.
      const currentAccess = draft.access ? clone(draft.access) : undefined;
      const currentPin = draft.settings.kiosk_pin;
      for (const key of Object.keys(draft)) delete (draft as unknown as Record<string, unknown>)[key];
      Object.assign(draft, replacement);
      if (currentAccess) draft.access = currentAccess; else delete draft.access;
      if (currentPin !== undefined) draft.settings.kiosk_pin = currentPin; else delete draft.settings.kiosk_pin;
    }); this.imported = undefined;
  }
  private renderBackup() {
    if (!this.admin) return this.adminOnly();
    return html`<h3>${this.tr("نسخ احتياطي واسترجاع", "Backup and restore")}</h3><p>${this.tr("الملف يحتوي تصميم بيتك وإعداداته. احفظه بشكل خاص؛ رمز قفل الشاشة لا يدخل الملف. الاسترجاع يستبدل التصميم وإعداداته بالكامل، مع إبقاء صلاحيات المستخدمين ورمز القفل الحاليين.", "The backup contains your home layout and settings. Keep it private; the screen PIN is excluded. Restore fully replaces layout settings while preserving current user-access rules and screen PIN.")}</p><button @click=${() => { const config = clone(this.ctx.config); delete config.settings.kiosk_pin; this.download("SmartNest-backup-" + new Date().toISOString().slice(0, 10) + ".json", config); }}>${this.tr("تنزيل نسخة احتياطية", "Download backup")}</button><label class="field upload"><span>${this.tr("استرجاع من ملف JSON؛ حتى ١ ميغابايت", "Restore JSON file; up to 1 MB")}</span><input type="file" accept=".json,application/json" @change=${this.importFile}></label>${this.imported ? html`<article><h4>${this.tr("معاينة النسخة المستوردة", "Imported backup preview")}</h4><p>${this.imported.settings.home_name || "SmartNest"} · ${this.imported.plan.floors.length} ${this.tr("طوابق", "floors")} · ${Object.keys(this.imported.rooms).length} ${this.tr("إعدادات غرف", "room settings")}</p><button @click=${() => this.restore(this.imported!)}>${this.tr("تأكيد الاسترجاع", "Confirm restore")}</button><button class="subtle" @click=${() => this.imported = undefined}>${this.tr("إلغاء", "Cancel")}</button></article>` : nothing}<h4>${this.tr("النسخ السابقة المحفوظة", "Saved previous versions")}</h4><button class="subtle" ?disabled=${this.busy} @click=${() => this.loadSection()}>${this.tr("تحديث السجل", "Refresh history")}</button>${this.versions.map(version => html`<div class="row"><span>${this.format(version.created_at)}</span><button @click=${() => this.restore(normalize(version.config))}>${this.tr("استرجاع", "Restore")}</button></div>`)}`;
  }
  private renderLicense() {
    const license = this.license; const remaining = license?.expires_at ? Math.ceil((license.expires_at * 1000 - Date.now()) / 86400000) : null;
    return html`<h3>${this.tr("ترخيص SmartNest", "SmartNest license")}</h3>${license ? html`<article><strong>${license.valid ? this.tr("الترخيص فعّال", "License active") : this.tr("يلزم التحقق من الترخيص", "License requires attention")}</strong>${license.customer_name ? html`<p>${license.customer_name}</p>` : nothing}<p>${this.tr("تاريخ الانتهاء: ", "Expires: ")}${license.expires_at === null ? this.tr("مدى الحياة", "Lifetime") : this.format(license.expires_at)}</p>${remaining !== null ? html`<p>${Math.max(0, remaining)} ${this.tr("يوم متبقٍ", "days remaining")}</p>${remaining <= 30 ? html`<p class="notice">${remaining <= 7 ? this.tr("اقترب الانتهاء جدًا؛ تواصل مع المزوّد للتجديد.", "Your license expires soon. Contact your provider to renew.") : this.tr("ترخيصك ينتهي خلال شهر. يمكنك التجديد بالمفتاح نفسه.", "Your license expires within a month. Renewal can retain the same key.")}</p>` : nothing}` : nothing}${license.offline_until ? html`<p class="hint">${this.tr("نهاية مهلة التحقق المحفوظة: ", "Cached validation deadline: ")}${this.format(license.offline_until)}</p>` : nothing}</article>` : html`<p>${this.tr("اضغط تحديث لقراءة حالة الترخيص.", "Refresh to read the license status.")}</p>`}<button ?disabled=${this.busy} @click=${() => this.loadSection()}>${this.tr("تحديث الحالة", "Refresh status")}</button><p><a href="https://smartnest.pro" target="_blank" rel="noopener noreferrer">${this.tr("التواصل مع SmartNest للتجديد والدعم", "Contact SmartNest for renewal and support")}</a></p><p class="hint">${this.tr("مفاتيح الترخيص وبيانات دخول Home Assistant لا تظهر هنا.", "License keys and Home Assistant credentials are never shown here.")}</p>`;
  }
  private chooseAccess(id: string) {
    this.accessUser = id; const current = this.ctx.config.access?.users[id]; this.accessAreas = [...current?.areas ?? []]; this.accessEntities = [...current?.entities ?? []]; this.guestDays = current?.guest_until ? Math.max(0, Math.ceil((current.guest_until * 1000 - Date.now()) / 86400000)) : 0;
  }
  private renderAccess() {
    if (!this.admin) return this.adminOnly();
    const existing = this.ctx.config.access?.users ?? {};
    return html`<h3>${this.tr("صلاحيات العرض والتحكم داخل SmartNest", "SmartNest access preferences")}</h3><p class="hint">${this.tr("هذه قيود داخل SmartNest فقط. صلاحيات Home Assistant الأصلية تُدار من إعداداته ولا يغيرها هذا النموذج. ترك القائمتين فارغتين يمنع جميع الأجهزة لهذا الحساب داخل SmartNest. لإعادة الوصول غير المقيّد استخدم إزالة القيود.", "These are SmartNest restrictions only. Native Home Assistant permissions remain managed in Home Assistant. Leaving both lists empty denies all entities in SmartNest. Use Remove restrictions to restore unrestricted access.")}</p>${this.users.length ? html`<label class="field"><span>${this.tr("المستخدم", "User")}</span><select .value=${this.accessUser} @change=${(event: Event) => this.chooseAccess((event.target as HTMLSelectElement).value)}><option value="">${this.tr("اختر مستخدمًا", "Choose a user")}</option>${this.users.map(user => html`<option value=${user.id} ?selected=${this.accessUser === user.id}>${user.name}</option>`)}</select></label>` : html`<label class="field"><span>${this.tr("معرّف المستخدم من إعدادات Home Assistant", "User ID from Home Assistant settings")}</span><input type="text" .value=${this.accessUser} @change=${(event: Event) => this.chooseAccess((event.target as HTMLInputElement).value.trim())}></label>`}<div class="grid"><label class="field"><span>${this.tr("الغرف المسموحة؛ تحديد متعدد", "Allowed areas; multiple selection")}</span><select multiple size="6" @change=${(event: Event) => this.accessAreas = Array.from((event.target as HTMLSelectElement).selectedOptions).map(option => option.value)}>${areas(this.ctx.hass).map(area => html`<option value=${area.area_id} ?selected=${this.accessAreas.includes(area.area_id)}>${area.name}</option>`)}</select></label><label class="field"><span>${this.tr("أجهزة إضافية مسموحة", "Additional allowed entities")}</span><select multiple size="6" @change=${(event: Event) => this.accessEntities = Array.from((event.target as HTMLSelectElement).selectedOptions).map(option => option.value)}>${this.entities.map(entity => html`<option value=${entity.entity_id} ?selected=${this.accessEntities.includes(entity.entity_id)}>${nameOf(this.ctx.hass, entity.entity_id)}</option>`)}</select></label></div><label class="field"><span>${this.tr("صلاحية الضيف بالأيام؛ صفر بدون حد زمني", "Guest duration in days; zero for no deadline")}</span>${this.fieldHelp("المهلة لا تمنح أجهزة تلقائيًا؛ حدد الغرف أو الأجهزة المسموحة أعلاه.", "A deadline grants no entities by itself. Select allowed areas or entities above.")}<input type="number" min="0" max="365" .value=${String(this.guestDays)} @change=${(event: Event) => this.guestDays = Math.max(0, Math.min(365, Number((event.target as HTMLInputElement).value)))}></label><button ?disabled=${!this.accessUser} @click=${() => { const user = this.accessUser; if (!user) return; this.ctx.saveLayout(config => { config.access ??= { users: {} }; config.access.users[user] = { areas: this.accessAreas.length ? [...this.accessAreas] : undefined, entities: this.accessEntities.length ? [...this.accessEntities] : undefined, guest_until: this.guestDays ? Math.floor(Date.now() / 1000) + this.guestDays * 86400 : undefined }; }); }}>${this.tr("تطبيق القيود", "Apply restrictions")}</button><h4>${this.tr("الحسابات المضبوطة", "Configured accounts")}</h4>${Object.entries(existing).map(([id, policy]) => html`<div class="row"><button class="entity" @click=${() => this.chooseAccess(id)}><strong>${this.users.find(user => user.id === id)?.name || id}</strong><small>${policy.guest_until ? this.format(policy.guest_until) : this.tr("بدون حد زمني", "No time limit")}</small></button><button class="subtle" @click=${() => { if (window.confirm(this.tr("إزالة قيود SmartNest لهذا الحساب؟", "Remove SmartNest restrictions for this account?"))) this.ctx.saveLayout(config => { if (config.access) delete config.access.users[id]; }); }}>${this.tr("إزالة القيود", "Remove restrictions")}</button></div>`)}`;
  }
  private renderActivity() {
    if (!this.admin) return this.adminOnly();
    return html`<h3>${this.tr("سجل أوامر SmartNest", "SmartNest activity")}</h3><p class="hint">${this.tr("يعرض الأوامر التي أُرسلت عبر SmartNest؛ قد توجد تغييرات أخرى من Home Assistant أو الأجهزة مباشرة.", "Shows actions sent through SmartNest. Other changes may come from Home Assistant or devices directly.")}</p><button ?disabled=${this.busy} @click=${() => this.loadSection()}>${this.tr("تحديث", "Refresh")}</button>${this.activity.length ? this.activity.map(event => html`<article><strong>${event.service === "state_changed" ? this.tr("تغيّر حالة جهاز", "Entity state changed") : event.domain + "." + event.service + " · " + (event.success ? this.tr("نجح", "Succeeded") : this.tr("تعذّر", "Failed"))}</strong><p>${this.format(event.at)} · ${this.users.find(user => user.id === event.user)?.name || (event.user === "homeassistant" ? "Home Assistant" : event.user)}</p>${event.from_state !== undefined && event.to_state !== undefined ? html`<p dir="auto">${event.from_state} → ${event.to_state}</p>` : nothing}<small>${(event.entities ?? []).map(id => nameOf(this.ctx.hass, id)).join("، ")}</small></article>`) : html`<p>${this.tr("لا توجد أوامر مسجلة حتى الآن.", "No recorded actions yet.")}</p>`}`;
  }
  private renderSchedules() {
    if (!this.admin) return this.adminOnly();
    return html`<h3>${this.tr("جدولة المشاهد", "Schedule scenes")}</h3><p class="hint">${this.tr("التنفيذ يتم في Home Assistant حتى لو أغلقت الشاشة. اختر وقتًا مستقبليًا بالتوقيت المحلي لهذه الشاشة.", "Home Assistant runs the schedule even when this screen is closed. Choose a future time in this screen’s local time zone.")}</p><form @submit=${(event: Event) => { event.preventDefault(); void this.run(async () => { const date = new Date(this.scheduleAt); if (!this.scheduleEntity || !Number.isFinite(date.getTime()) || date.getTime() <= Date.now()) throw new Error(this.tr("اختر مشهدًا ووقتًا مستقبليًا صالحًا.", "Choose a scene and valid future time.")); await this.ctx.hass.callWS({ type: "smartnest_pro/schedule/add", entity_id: this.scheduleEntity, at: date.toISOString() }); this.notice = this.tr("تمت إضافة الجدولة.", "Schedule added."); await this.loadSection(); }); }}><label class="field"><span>${this.tr("المشهد أو السكربت", "Scene or script")}</span>${this.fieldHelp("اختر مشهدًا موجودًا ومُجرّبًا؛ سيعمل مرة واحدة في الموعد المحدد.", "Choose an existing, tested scene; it will run once at the selected time.")} ${this.entitySelect(this.scheduleEntity, value => this.scheduleEntity = value, this.sceneIds)}</label><label class="field"><span>${this.tr("موعد التنفيذ", "Run at")}</span><input required type="datetime-local" .value=${this.scheduleAt} @change=${(event: Event) => this.scheduleAt = (event.target as HTMLInputElement).value}></label><button ?disabled=${this.busy}>${this.tr("إضافة الجدولة", "Add schedule")}</button></form>${this.schedules.map(schedule => html`<div class="row"><div><strong>${nameOf(this.ctx.hass, schedule.entity_id)}</strong><p>${this.format(schedule.at)}</p></div><button class="subtle" ?disabled=${this.busy} @click=${() => this.run(async () => { await this.ctx.hass.callWS({ type: "smartnest_pro/schedule/cancel", id: schedule.id }); await this.loadSection(); })}>${this.tr("إلغاء", "Cancel")}</button></div>`)}`;
  }
  private renderEnergy() {
    return html`<h3>${this.tr("ميزانية الطاقة", "Energy budget")}</h3><p class="hint">${this.tr("التكلفة تقديرية وفق التعرفة التي تدخلها. حساس الطاقة التراكمي ليس استهلاك الشهر وحده؛ تظهر المقارنات فقط عندما تتوفر إحصائيات Home Assistant.", "Costs are estimates using your tariff. A cumulative meter is not monthly consumption; comparisons require Home Assistant statistics.")}</p>${this.admin ? html`<label class="field"><span>${this.tr("حساس قدرة البيت", "Home power sensor")}</span>${this.fieldHelp("اختر حساس القدرة الذي يمثل استهلاك البيت بالكيلوواط أو الواط. التنبيه يعتمد على هذا الحساس وحده.", "Choose the sensor representing your home power in W or kW. Only this sensor drives the threshold alert.")}${this.entitySelect(this.exp.power_entity ?? "", value => this.updateExperience(e => e.power_entity = value || undefined), this.entities.filter(entity => entity.attributes.device_class === "power").map(entity => entity.entity_id))}</label><div class="grid">${([ ["tariff", this.tr("سعر الكيلوواط ساعة", "Price per kWh"), 0.01], ["monthly_budget", this.tr("الميزانية الشهرية", "Monthly budget"), 1], ["power_alert_kw", this.tr("تنبيه قدرة أعلى من (kW)", "Power alert above (kW)"), 0.1] ] as const).map(([key, label, step]) => html`<label class="field"><span>${label}</span><input type="number" min="0" step=${step} .value=${String(this.exp[key] ?? "")} @change=${(event: Event) => { const input = event.target as HTMLInputElement; const value = input.value === "" ? undefined : Number(input.value); if (value !== undefined && (!Number.isFinite(value) || value < 0)) return; this.updateExperience(e => e[key] = value); }}></label>`)}<label class="field"><span>${this.tr("رمز العملة", "Currency")}</span><input type="text" maxlength="8" .value=${this.exp.currency ?? "₪"} @change=${(event: Event) => this.updateExperience(e => e.currency = (event.target as HTMLInputElement).value.trim().slice(0, 8))}></label></div>` : nothing}<h4>${this.tr("القدرة الآن", "Power right now")}</h4>${this.entities.filter(entity => entity.attributes.device_class === "power" && powerKw(entity) != null).map(entity => html`<div class="row"><span>${nameOf(this.ctx.hass, entity.entity_id)}</span><strong>${powerKw(entity)!.toFixed(2)} kW${this.exp.tariff ? " · " + (powerKw(entity)! * this.exp.tariff).toFixed(2) + " " + (this.exp.currency ?? "₪") + this.tr("/ساعة", "/hour") : ""}</strong></div>`)}`;
  }
  private async checkConnection() {
    await this.run(async () => {
      const started = performance.now(); let timer: ReturnType<typeof setTimeout> | undefined;
      try {
        const response = await Promise.race([
          this.ctx.hass.callWS<{ valid: boolean }>({ type: "smartnest_pro/license/status" }),
          new Promise<never>((_, reject) => { timer = setTimeout(() => reject(new Error(this.tr("انتهت مهلة الاتصال بعد ١٠ ثوانٍ.", "Connection timed out after 10 seconds."))), 10_000); }),
        ]);
        if (!response || typeof response.valid !== "boolean") throw new Error(this.tr("استجابة الاتصال غير متوقعة.", "Unexpected connection response."));
        this.connectionResult = { checkedAt: new Date().toISOString(), ok: true, latency: Math.round(performance.now() - started), validLicense: response.valid };
      } catch (error) {
        this.connectionResult = { checkedAt: new Date().toISOString(), ok: false }; throw error;
      } finally { clearTimeout(timer); }
    });
  }
  private diagnostics() {
    const report = { product: "SmartNest Pro", version: __SN_VERSION__, generated_at: new Date().toISOString(), language: this.ctx.lang, entity_count: this.entities.length, area_count: areas(this.ctx.hass).length, unavailable_count: this.entities.filter(e => ["unknown", "unavailable"].includes(e.state)).length, missing_link_count: this.missingLinks().length, floor_count: this.ctx.config.plan.floors.length, theme: this.ctx.config.settings.theme, connection: this.connectionResult ? { checked_at: this.connectionResult.checkedAt, reachable: this.connectionResult.ok, round_trip_ms: this.connectionResult.latency ?? null } : null };
    return html`<h4>${this.tr("تشخيص الاتصال", "Diagnostics")}</h4><button ?disabled=${this.busy} @click=${this.checkConnection}>${this.tr("فحص الاتصال الآن", "Check connection now")}</button>${this.connectionResult ? html`<p role="status">${this.connectionResult.ok ? this.tr("وصل رد فعلي من Home Assistant", "Home Assistant responded") + " · " + this.connectionResult.latency + " ms" : this.tr("تعذّر وصول رد من Home Assistant.", "Home Assistant did not respond.")} · ${this.format(this.connectionResult.checkedAt)}</p>${this.connectionResult.ok && !this.connectionResult.validLicense ? html`<p class="hint">${this.tr("الاتصال يعمل، لكن الترخيص يحتاج إلى تحقق.", "The connection works, but the license needs attention.")}</p>` : nothing}` : nothing}<p>SmartNest Pro ${__SN_VERSION__} · ${report.entity_count} ${this.tr("جهاز", "entities")} · ${report.area_count} ${this.tr("غرفة", "areas")}</p><p>${report.unavailable_count} ${this.tr("غير متصلة", "unavailable")} · ${report.missing_link_count} ${this.tr("روابط مفقودة", "missing links")}</p><button @click=${() => this.download("SmartNest-support.json", report)}>${this.tr("تنزيل تقرير دعم آمن", "Download sanitized support report")}</button><p class="hint">${this.tr("التقرير يضم أعدادًا وإصدارًا فقط؛ بدون أسماء الأجهزة أو معرّفاتها أو المخطط أو رموز الدخول.", "The report contains counts and version only, with no entity names, IDs, layout or credentials.")}</p>`;
  }
  private renderHelp() {
    const steps = [this.tr("ابدأ بالإعداد الأول لاختيار اسم البيت واللغة والأجهزة الأساسية.", "Start with setup to choose the home name, language and key entities."), this.tr("افتح تعديل المخطط واربط كل غرفة بمنطقة Home Assistant، ثم احفظ التصميم.", "Edit the floor plan, link rooms to Home Assistant areas, and save your layout."), this.tr("أضف مفضلتك واحفظ نسخة احتياطية. اضغط مطولًا على الجهاز لخياراته الإضافية.", "Choose favorites and download a backup. Hold an entity for additional controls.")];
    return html`<h3>${this.tr("مساعدة وجولة سريعة", "Help and quick tour")}</h3><article><strong>${this.tourStep + 1} / 3</strong><p>${steps[this.tourStep]}</p><button ?disabled=${this.tourStep === 0} class="subtle" @click=${() => this.tourStep--}>${this.tr("السابق", "Previous")}</button><button ?disabled=${this.tourStep === 2} @click=${() => this.tourStep++}>${this.tr("التالي", "Next")}</button></article>${this.admin ? html`<button @click=${() => { this.ctx.closeSheet(); window.dispatchEvent(new CustomEvent("sn-open-setup")); }}>${this.tr("فتح إعداد أول تشغيل", "Open first-run setup")}</button>` : nothing}<details><summary>${this.tr("الجهاز لا يستجيب", "An entity does not respond")}</summary><p>${this.tr("افتح التنبيهات، تحقق من حالة الجهاز وآخر تحديث له، ثم جرّبه من Home Assistant. لا تكرر الضغط أثناء تنفيذ الأمر.", "Check notifications and the entity’s state and update time, then try it from Home Assistant. Avoid repeated presses during an action.")}</p></details><details><summary>${this.tr("كيف أحافظ على التصميم؟", "How do I protect my layout?")}</summary><p>${this.tr("من النسخ الاحتياطي يمكنك تنزيل ملف واسترجاعه بعد المعاينة، أو العودة لنسخة سابقة. احفظ تعديلاتك قبل إغلاق وضع التعديل.", "Download a backup and restore it after reviewing the preview, or restore a previous saved version. Save edits before leaving edit mode.")}</p></details><details><summary>${this.tr("كيف أجدد الترخيص؟", "How do I renew?")}</summary><p>${this.tr("افتح ترخيصي لمعرفة موعد الانتهاء، وتواصل مع المزوّد. يمكنه تمديد نفس المفتاح بدون تغيير التصميم.", "Open My license for the expiry date and contact your provider. They can extend the same key without changing your layout.")}</p></details>${this.admin ? html`<h4>${this.tr("نسخ إعدادات غرفة", "Copy room settings")}</h4><p class="hint">${this.tr("ينسخ إعدادات الغرفة وروابط حسّاساتها؛ راجع الأجهزة المرتبطة بعد النسخ.", "Copies room settings and sensor links. Review linked entities after copying.")}</p><div class="grid">${(["from", "to"] as const).map(kind => html`<label class="field"><span>${kind === "from" ? this.tr("من غرفة", "From room") : this.tr("إلى غرفة", "To room")}</span><select .value=${kind === "from" ? this.copyFrom : this.copyTo} @change=${(event: Event) => { if (kind === "from") this.copyFrom = (event.target as HTMLSelectElement).value; else this.copyTo = (event.target as HTMLSelectElement).value; }}><option value="">—</option>${areas(this.ctx.hass).map(area => html`<option value=${area.area_id} ?selected=${(kind === "from" ? this.copyFrom : this.copyTo) === area.area_id}>${area.name}</option>`)}</select></label>`)}</div><button ?disabled=${!this.copyFrom || !this.copyTo || this.copyFrom === this.copyTo} @click=${() => { if (window.confirm(this.tr("استبدال إعدادات الغرفة المستهدفة؟", "Replace the target room settings?"))) this.ctx.saveLayout(config => { const previousName = config.rooms[this.copyTo]?.name; config.rooms[this.copyTo] = { ...clone(config.rooms[this.copyFrom] ?? {}), name: previousName }; }); }}>${this.tr("نسخ الإعدادات", "Copy settings")}</button>` : nothing}${this.diagnostics()}`;
  }
  private adminOnly() { return html`<p>${this.tr("هذه الأدوات متاحة لمسؤول المنزل فقط.", "These tools are available to home administrators only.")}</p>`; }
  render() {
    if (!this.ctx) return nothing;
    const tabs: [Section, string][] = [["overview", this.tr("الملخص", "Overview")], ["search", this.tr("البحث", "Search")], ["alerts", this.tr("التنبيهات", "Alerts")], ["maintenance", this.tr("الصيانة", "Maintenance")], ["preferences", this.tr("تفضيلاتي", "Preferences")], ["energy", this.tr("الطاقة", "Energy")], ["license", this.tr("ترخيصي", "My license")], ["backup", this.tr("النسخ الاحتياطي", "Backups")], ["access", this.tr("الصلاحيات", "Access")], ["activity", this.tr("السجل", "Activity")], ["schedules", this.tr("الجدولة", "Schedules")], ["help", this.tr("المساعدة", "Help")]];
    const renderers: Record<Section, () => unknown> = { overview: () => this.renderOverview(), search: () => this.renderSearch(), alerts: () => this.renderAlerts(), maintenance: () => this.renderMaintenance(), preferences: () => this.renderPreferences(), backup: () => this.renderBackup(), license: () => this.renderLicense(), access: () => this.renderAccess(), activity: () => this.renderActivity(), schedules: () => this.renderSchedules(), energy: () => this.renderEnergy(), help: () => this.renderHelp() };
    return html`<div dir=${this.ctx.rtl ? "rtl" : "ltr"}><nav aria-label=${this.tr("أقسام مركز البيت", "Home center sections")}>${tabs.filter(([id]) => this.admin || !["backup", "access", "activity", "schedules"].includes(id)).map(([id, title]) => html`<button aria-pressed=${this.section === id} @click=${() => this.changeSection(id)}>${title}</button>`)}</nav>${this.busy ? html`<p role="status" class="hint">${this.tr("جارٍ تنفيذ الطلب…", "Working…")}</p>` : nothing}${this.notice ? html`<p role=${this.failed ? "alert" : "status"} class="notice">${this.notice}</p>` : nothing}<section>${renderers[this.section]()}</section></div>`;
  }
  static styles = [shared, fieldStyles, css`
    :host{display:block;color:var(--sn-text);font-family:var(--sn-font)}nav{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:24px}button{font:inherit;cursor:pointer;color:var(--sn-text);background:var(--sn-glass-light);border:1px solid var(--sn-glass-border);padding:10px 14px;border-radius:12px}button:hover,button[aria-pressed=true]{background:var(--sn-chip);border-color:var(--sn-accent)}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--sn-accent);outline-offset:3px}h3{font-size:20px;margin:0 0 18px}h4{font-size:15px;margin:18px 0 12px}p{line-height:1.8;font-size:13px}a{color:var(--sn-accent)}small,.hint{color:var(--sn-text-dim);font-size:12px;line-height:1.7}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:20px}.metrics>div,article{padding:16px;background:var(--sn-glass-light);border:1px solid var(--sn-glass-border);border-radius:15px;margin-bottom:12px}.metrics strong{display:block;font-size:25px}.metrics span{font-size:12px;color:var(--sn-text-dim)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px;border-bottom:1px solid var(--sn-glass-border)}.row p{margin:6px 0}.entity{background:transparent;border:0;text-align:start;display:grid;gap:6px;min-width:0;overflow-wrap:anywhere}.field-help{display:block;margin:2px 0 8px}.page-drag{cursor:grab}.star{font-size:24px;color:var(--sn-accent)}.results{display:flex;gap:8px;flex-wrap:wrap}.subtle{background:transparent}.notice{padding:12px;border:1px solid var(--sn-accent);border-radius:12px;background:var(--sn-glass-light)}input[type=search],input[type=date],input[type=time],input[type=datetime-local]{width:100%;min-height:44px;padding:10px;border:1px solid var(--sn-glass-border);background:var(--sn-glass-light);border-radius:12px;color:var(--sn-text);font:inherit}select[multiple]{height:auto;min-height:120px}.upload{margin-top:24px}details{border-bottom:1px solid var(--sn-glass-border);padding:14px 0}summary{cursor:pointer;font-size:14px}@media(max-width:620px){.metrics{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}nav button{font-size:12px;padding:8px 10px}.row{align-items:flex-start}.row>div{min-width:0}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
  `];
}
